<?php
/** Generic archive card. @package Travelix_Flex */
?>
<article <?php post_class( 'archive-card reveal' ); ?>><a class="archive-card__media" href="<?php the_permalink(); ?>"><?php if ( has_post_thumbnail() ) : the_post_thumbnail( 'large', array( 'loading' => 'lazy', 'decoding' => 'async' ) ); else : ?><img src="<?php echo esc_url( get_theme_file_uri( '/assets/images/demo-destination.svg' ) ); ?>" alt="" loading="lazy" decoding="async"><?php endif; ?></a><div class="archive-card__body"><time datetime="<?php echo esc_attr( get_the_date( DATE_W3C ) ); ?>" dir="auto"><?php echo esc_html( get_the_date() ); ?></time><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p><?php echo esc_html( wp_trim_words( get_the_excerpt(), 22 ) ); ?></p><a class="link-arrow" href="<?php the_permalink(); ?>"><?php esc_html_e( 'ادامه مطلب', 'travelix-flex' ); ?> <?php echo travelix_flex_icon( 'arrow' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?></a></div></article>
